insert into anagrafica.catalogo_patologie
  (codice, nome, sinonimi, tipo, area, esenzione, orpha, icd9cm, descrizione, segni_allarme,
   diagnosi, follow_up, specialisti, emergenza, note, fonti, ordine) values
('sferocitosi', 'Sferocitosi ereditaria', '{}'::text[], 'rara', 'ematologia', 'RDG010', 822, '{}'::text[], 'Anemia emolitica ereditaria da difetto delle proteine di membrana del globulo rosso; la più frequente nei bambini di origine europea.', array['Ittero neonatale importante o prolungato', 'Pallore, stanchezza', 'Milza ingrandita', 'Calcoli della colecisti anche in età scolare', 'Familiari con anemia, splenectomia o colecistectomia'], 'Emocromo con indici (MCHC elevato), striscio con sferociti, reticolociti, bilirubina; test di fragilità osmotica o EMA test.', array['Ematologo pediatra', 'Acido folico se indicato', 'Ecografia della colecisti periodica', 'Vaccinazioni complete, comprese quelle per l''asplenia se splenectomizzati'], 'Ematologo pediatra', 'Infezione da parvovirus B19 (quinta malattia): rischio di crisi aplastica con pallore improvviso, controllare subito l''emocromo.', 'Esente con il codice RDG010 (anemie ereditarie). Tra le malattie rare più frequenti in età pediatrica nel Registro Lombardo Malattie Rare (dati al 31/12/2023).', '[]'::jsonb, 590),
('pti_cronica', 'Piastrinopenia autoimmune cronica (PTI cronica)', '{}'::text[], 'rara', 'ematologia', 'RDG031', null, '{}'::text[], 'Piastrinopenia da distruzione immunomediata che persiste oltre 12 mesi.', array['Petecchie ed ecchimosi senza traumi importanti', 'Sanguinamento dal naso o dalle gengive', 'Piastrine basse con il resto dell''emocromo normale'], 'Emocromo e striscio periferico; esclusione delle altre cause; nella forma acuta del bambino la maggior parte guarisce entro alcuni mesi.', array['Ematologo pediatra', 'Evitare FANS e sport di contatto se le piastrine sono molto basse'], 'Ematologo pediatra', 'Sanguinamento abbondante, mucoso o qualsiasi sintomo neurologico (cefalea intensa, vomito): pronto soccorso.', 'L''esenzione riguarda le forme croniche (RDG031: piastrinopatie autoimmuni primarie croniche).', '[]'::jsonb, 600),
('glomerulopatie', 'Glomerulopatie primitive', '{}'::text[], 'rara', 'nefro', 'RJG020', null, '{}'::text[], 'Malattie primitive del glomerulo renale (es. glomerulosclerosi focale segmentale, nefropatia membranosa, nefropatia a IgA).', array['Edemi (palpebre al risveglio, caviglie)', 'Urine schiumose o scure', 'Proteinuria o ematuria all''esame delle urine', 'Ipertensione arteriosa'], 'Esame urine con rapporto proteine/creatinina, funzione renale, albumina; biopsia renale nei casi indicati.', array['Nefrologo pediatra', 'Pressione arteriosa, proteinuria e funzione renale periodiche'], 'Nefrologo pediatra', null, 'Dall''esenzione è esclusa la glomerulopatia a lesioni minime, la causa più comune di sindrome nefrosica nel bambino.', '[]'::jsonb, 610),
('mucopolisaccaridosi', 'Mucopolisaccaridosi', array['MPS', 'Sindrome di Hurler', 'Sindrome di Hunter'], 'rara', 'metabolico', 'RCG140', 579, '{}'::text[], 'Malattie lisosomiali da accumulo di glicosaminoglicani (es. Hurler, Hunter, Sanfilippo, Morquio).', array['Tratti del volto che si fanno grossolani', 'Ernie ombelicali e inguinali ricorrenti', 'Rigidità articolare, deformità scheletriche', 'Otiti ricorrenti, ipoacusia, apnee nel sonno', 'Epatosplenomegalia, regressione dello sviluppo in alcune forme'], 'Glicosaminoglicani urinari, dosaggio enzimatico, analisi genetica.', array['Centro per le malattie metaboliche: terapia enzimatica sostitutiva o trapianto nelle forme indicate', 'Cardiologia, otorino, ortopedia, sonno'], 'Centro per le malattie metaboliche ereditarie', null, 'Tra le malattie rare più frequenti in età pediatrica nel Registro Lombardo Malattie Rare (dati al 31/12/2023).', '[]'::jsonb, 620),
('angioedema_ereditario', 'Angioedema ereditario', '{}'::text[], 'rara', 'immunologia', 'RC0190', 91378, '{}'::text[], 'Deficit ereditario dell''inibitore della C1 esterasi con episodi di edema mediati dalla bradichinina.', array['Gonfiori ricorrenti senza orticaria né prurito (arti, volto, genitali)', 'Crisi di dolore addominale intenso', 'Familiari con episodi simili'], 'C4, livello e funzione del C1 inibitore.', array['Centro di riferimento: farmaci per la crisi e profilassi prima di interventi o cure dentarie', 'Piano scritto per la scuola'], 'Immunologo / allergologo del centro di riferimento', 'Gonfiore della gola, della lingua o difficoltà a respirare: 118. Adrenalina, antistaminici e cortisone non sono efficaci: servono i farmaci specifici.', 'Tra le malattie rare più frequenti in età pediatrica nel Registro Lombardo Malattie Rare (dati al 31/12/2023).', '[]'::jsonb, 630),
('kallmann', 'Sindrome di Kallmann', '{}'::text[], 'rara', 'endocrino', 'RC0020', 478, '{}'::text[], 'Ipogonadismo ipogonadotropo congenito con riduzione o assenza dell''olfatto.', array['Mancato inizio della pubertà', 'Micropene o criptorchidismo nel neonato maschio', 'Olfatto assente o ridotto'], 'LH, FSH, steroidi sessuali; valutazione dell''olfatto; risonanza; analisi genetica.', array['Endocrinologo pediatra: induzione puberale', 'Salute dell''osso'], 'Endocrinologo pediatra', null, 'Tra le malattie rare più frequenti in età pediatrica nel Registro Lombardo Malattie Rare (dati al 31/12/2023).', '[]'::jsonb, 640),
('alfa1_antitripsina', 'Carenza congenita di alfa-1-antitripsina', '{}'::text[], 'rara', 'gastro', 'RC0200', 60, '{}'::text[], 'Malattia genetica che nel bambino può causare colestasi neonatale ed epatopatia; in età adulta enfisema.', array['Ittero prolungato con feci chiare nel neonato', 'Transaminasi elevate senza spiegazione', 'Epatomegalia'], 'Dosaggio dell''alfa-1-antitripsina e fenotipo/genotipo (es. PiZZ).', array['Epatologo pediatra', 'Evitare il fumo passivo (e attivo in adolescenza)', 'Test dei familiari'], 'Epatologo pediatra', null, 'Tra le malattie rare più frequenti in età pediatrica nel Registro Lombardo Malattie Rare (dati al 31/12/2023).', '[]'::jsonb, 650),
('istiocitosi', 'Istiocitosi a cellule di Langerhans e istiocitosi croniche', '{}'::text[], 'rara', 'oncologia', 'RCG150', 389, '{}'::text[], 'Proliferazione di cellule istiocitarie che può interessare osso, cute e altri organi.', array['Lesioni ossee dolorose o tumefazioni del cranio', 'Dermatite seborroica-simile ostinata, soprattutto nel lattante', 'Otorrea cronica', 'Sete e urine abbondanti (diabete insipido)'], 'Biopsia della lesione; stadiazione in centro di oncoematologia pediatrica.', array['Centro di oncoematologia pediatrica (AIEOP)', 'Controlli per recidive e sequele (diabete insipido, ortopediche)'], 'Oncoematologo pediatra', null, 'Tra le malattie rare più frequenti in età pediatrica nel Registro Lombardo Malattie Rare (dati al 31/12/2023).', '[]'::jsonb, 660),
('iperinsulinismo', 'Iperinsulinismo congenito', '{}'::text[], 'rara', 'endocrino', 'RCG061', 276556, '{}'::text[], 'Eccessiva secrezione di insulina con ipoglicemie gravi e persistenti, causa principale di ipoglicemia persistente nel neonato e nel lattante.', array['Ipoglicemie ricorrenti nel neonato, anche con convulsioni', 'Neonato macrosomico', 'Necessità di glucosio ad alte dosi'], 'Dosaggi durante l''ipoglicemia (insulina, chetoni, acidi grassi); test genetici; PET con F-DOPA nelle forme focali.', array['Centro di endocrinologia pediatrica', 'Sviluppo neurologico'], 'Endocrinologo pediatra', 'Ipoglicemia: zuccheri rapidi se cosciente, altrimenti glucagone o glucosio endovena e 118.', 'Tra le malattie rare più frequenti in età pediatrica nel Registro Lombardo Malattie Rare (dati al 31/12/2023).', '[]'::jsonb, 670),
('ciclo_urea', 'Difetti del ciclo dell''urea e iperammoniemie ereditarie', '{}'::text[], 'rara', 'metabolico', 'RCG050', null, '{}'::text[], 'Difetti enzimatici che impediscono lo smaltimento dell''ammoniaca.', array['Neonato che dopo pochi giorni di benessere diventa sonnolento, rifiuta il pasto, vomita', 'Nel bambino: vomito ricorrente, avversione alle proteine, episodi di confusione o atassia'], 'Ammoniemia urgente (prelievo correttamente trattato), aminoacidi plasmatici, acido orotico urinario; analisi genetica. Alcune forme sono nello screening neonatale esteso.', array['Centro metabolico: dieta ipoproteica controllata e farmaci', 'Piano di emergenza scritto'], 'Centro per le malattie metaboliche ereditarie', 'Vomito, febbre o digiuno possono scatenare scompensi: seguire il piano d''emergenza e andare in ospedale.', 'Tra le malattie rare più frequenti in età pediatrica nel Registro Lombardo Malattie Rare (dati al 31/12/2023).', '[]'::jsonb, 680),
('deficit_biotinidasi', 'Difetti responsivi alla biotina (deficit di biotinidasi)', '{}'::text[], 'rara', 'metabolico', 'RCG092', 79241, '{}'::text[], 'Difetto del riciclo della biotina; si cura con biotina per bocca. Incluso nello screening neonatale esteso.', array['Positività allo screening neonatale', 'Se non trattato: convulsioni, ipotonia, dermatite, alopecia, ipoacusia'], 'Screening neonatale esteso e dosaggio dell''attività della biotinidasi.', array['Biotina a vita', 'Udito e vista'], 'Centro per le malattie metaboliche ereditarie', null, 'Tra le malattie rare più frequenti in età pediatrica nel Registro Lombardo Malattie Rare (dati al 31/12/2023).', '[]'::jsonb, 690),
('intolleranza_fruttosio', 'Intolleranza ereditaria al fruttosio', '{}'::text[], 'rara', 'metabolico', 'RCG060', 469, '{}'::text[], 'Deficit dell''aldolasi B: fruttosio, saccarosio e sorbitolo diventano tossici.', array['Sintomi all''introduzione di frutta, verdura o zucchero nello svezzamento: vomito, pallore, sudorazione, ipoglicemia', 'Avversione spontanea ai dolci e alla frutta', 'Epatomegalia, scarsa crescita'], 'Analisi genetica del gene ALDOB.', array['Dieta senza fruttosio, saccarosio e sorbitolo', 'Attenzione agli eccipienti dei farmaci (sciroppi)'], 'Centro per le malattie metaboliche ereditarie', null, 'Esente con il codice RCG060 (difetti del metabolismo dei carboidrati). Tra le malattie rare più frequenti in età pediatrica nel Registro Lombardo Malattie Rare (dati al 31/12/2023).', '[]'::jsonb, 700),
('mcad', 'Difetti dell''ossidazione degli acidi grassi (es. deficit di MCAD)', '{}'::text[], 'rara', 'metabolico', 'RCG074', 42, '{}'::text[], 'Difetti mitocondriali che impediscono di usare i grassi come energia durante il digiuno. Inclusi nello screening neonatale esteso.', array['Positività allo screening neonatale', 'Ipoglicemia senza chetoni durante digiuno o malattia', 'Letargia, vomito, convulsioni'], 'Screening neonatale esteso (acilcarnitine), conferma genetica.', array['Evitare il digiuno prolungato', 'Piano d''emergenza scritto per le malattie intercorrenti'], 'Centro per le malattie metaboliche ereditarie', 'Vomito o impossibilità ad alimentarsi: glucosio endovena in ospedale senza attendere l''ipoglicemia.', 'Tra le malattie rare più frequenti in età pediatrica nel Registro Lombardo Malattie Rare (dati al 31/12/2023).', '[]'::jsonb, 710),
('poliposi_familiare', 'Poliposi adenomatosa familiare', '{}'::text[], 'rara', 'oncologia', 'RB0050', 733, '{}'::text[], 'Malattia autosomica dominante del gene APC con centinaia di polipi del colon e rischio di carcinoma.', array['Familiare con poliposi o tumore del colon in giovane età', 'Sangue nelle feci, anemia', 'Osteomi, cisti epidermoidi, ipertrofia congenita dell''epitelio pigmentato della retina'], 'Test genetico APC nei familiari a rischio.', array['Colonscopia di sorveglianza dall''adolescenza (di solito dai 10–12 anni) nei portatori', 'Nei primi anni alcuni centri controllano anche l''alfa-fetoproteina (epatoblastoma)'], 'Gastroenterologo pediatra, genetista', null, 'Tra le malattie rare più frequenti in età pediatrica nel Registro Lombardo Malattie Rare (dati al 31/12/2023).', '[]'::jsonb, 720),
('deficit_gh_congenito', 'Deficit congenito isolato di ormone della crescita', '{}'::text[], 'rara', 'endocrino', 'RC0021', null, '{}'::text[], 'Forma congenita di deficit di GH, con codice di malattia rara distinto dal nanismo ipofisario (039).', array['Rallentamento della velocità di crescita fin dai primi anni', 'Nel neonato: ipoglicemie, micropene, ittero prolungato'], 'IGF-1, test di stimolo, età ossea, risonanza ipotalamo-ipofisaria, analisi genetica nelle forme familiari.', array['Terapia con GH secondo la Nota AIFA 39', 'Crescita ogni 3–6 mesi'], 'Endocrinologo pediatra', null, 'Tra le malattie rare più frequenti in età pediatrica nel Registro Lombardo Malattie Rare (dati al 31/12/2023).', '[]'::jsonb, 730),
('leigh', 'Malattia di Leigh', '{}'::text[], 'rara', 'neuro', 'RF0030', 506, '{}'::text[], 'Encefalopatia mitocondriale progressiva, di solito con esordio nei primi due anni.', array['Regressione delle tappe dello sviluppo, spesso dopo un''infezione', 'Ipotonia, difficoltà di alimentazione', 'Disturbi del movimento oculare, respiro irregolare', 'Acido lattico elevato'], 'Lattato nel sangue e nel liquor, risonanza encefalo, analisi genetiche.', array['Centro di neurologia pediatrica e malattie mitocondriali', 'Nutrizione e respiro'], 'Neurologo pediatra', null, 'Tra le malattie rare più frequenti in età pediatrica nel Registro Lombardo Malattie Rare (dati al 31/12/2023).', '[]'::jsonb, 740),
('rachitismo_ipofosfatemico', 'Rachitismo ipofosfatemico vitamina D resistente', '{}'::text[], 'rara', 'scheletro', 'RC0170', null, '{}'::text[], 'Perdita renale di fosfato su base genetica (più spesso legata all''X, gene PHEX).', array['Gambe arcuate quando il bambino inizia a camminare', 'Bassa statura', 'Ascessi dentari spontanei', 'Fosfatemia bassa con calcemia normale'], 'Fosforo, fosfatasi alcalina, riassorbimento tubulare dei fosfati, radiografie; analisi genetica.', array['Endocrinologo/nefrologo pediatra: terapia con fosfati e calcitriolo o farmaci specifici', 'Ortopedia, odontoiatria'], 'Endocrinologo pediatra', null, 'Tra le malattie rare più frequenti in età pediatrica nel Registro Lombardo Malattie Rare (dati al 31/12/2023).', '[]'::jsonb, 750),
('distrofie_miotoniche', 'Distrofie miotoniche (malattia di Steinert)', '{}'::text[], 'rara', 'neuromuscolare', 'RFG090', 273, '{}'::text[], 'Malattia multisistemica autosomica dominante; la forma congenita si manifesta nel neonato figlio di madre affetta.', array['Neonato ipotonico con difficoltà a respirare e succhiare', 'Madre con miotonia (difficoltà a rilasciare la presa)', 'Nel bambino: ritardo dello sviluppo, difficoltà di apprendimento'], 'Analisi genetica (espansione CTG nel gene DMPK).', array['Centro neuromuscolare', 'ECG e cardiologia periodici (aritmie)', 'Respiro, vista (cataratta), endocrinologia'], 'Centro neuromuscolare', 'Rischio di complicanze con l''anestesia: segnalarlo sempre.', null, '[]'::jsonb, 760),
('neuropatie_ereditarie', 'Neuropatie ereditarie (malattia di Charcot-Marie-Tooth)', '{}'::text[], 'rara', 'neuromuscolare', 'RFG060', 166, '{}'::text[], 'Neuropatie periferiche genetiche, la più frequente è la Charcot-Marie-Tooth.', array['Piede cavo, dita a martello', 'Cadute frequenti, difficoltà a camminare sui talloni', 'Familiari con problemi simili'], 'Visita neurologica, elettroneurografia, analisi genetica.', array['Fisioterapia e ortesi', 'Ortopedia'], 'Neurologo pediatra', null, 'Alcuni farmaci (es. vincristina) possono peggiorare la neuropatia.', '[]'::jsonb, 770),
('narcolessia', 'Narcolessia', '{}'::text[], 'rara', 'neuro', 'RF0150', null, '{}'::text[], 'Disturbo del sonno con eccessiva sonnolenza diurna, spesso con cataplessia; esordio frequente in età scolare e adolescenza.', array['Sonnolenza durante il giorno con addormentamenti improvvisi', 'Cedimenti muscolari con le emozioni (cataplessia)', 'Allucinazioni all''addormentamento, paralisi del sonno', 'Aumento di peso rapido o pubertà precoce nel bambino'], 'Polisonnografia e test delle latenze multiple del sonno in centro specializzato.', array['Centro di medicina del sonno', 'Supporto scolastico'], 'Neurologo / centro di medicina del sonno', null, null, '[]'::jsonb, 780),
('dermatomiosite', 'Dermatomiosite giovanile', '{}'::text[], 'rara', 'reumatologia', 'RM0010', 221, '{}'::text[], 'Miopatia infiammatoria autoimmune con lesioni cutanee caratteristiche.', array['Eritema violaceo delle palpebre, papule sul dorso delle mani', 'Debolezza muscolare prossimale (scale, alzarsi da terra)', 'Stanchezza, febbricola'], 'CK e altri enzimi muscolari, risonanza muscolare, autoanticorpi; biopsia nei casi dubbi.', array['Reumatologo pediatra', 'Calcinosi, deglutizione e respiro'], 'Reumatologo pediatra', 'Difficoltà a deglutire, voce nasale o respiro difficoltoso: valutazione urgente.', null, '[]'::jsonb, 790),
('colangite_sclerosante', 'Colangite sclerosante primitiva', '{}'::text[], 'rara', 'gastro', 'RI0050', 171, '{}'::text[], 'Infiammazione cronica delle vie biliari, nel bambino spesso associata a malattia infiammatoria cronica intestinale.', array['Gamma-GT elevate in bambino con colite', 'Prurito, ittero', 'Epatomegalia'], 'Esami di funzionalità epatica, colangio-RM.', array['Epatologo pediatra', 'Sorveglianza della malattia intestinale associata'], 'Epatologo pediatra', null, null, '[]'::jsonb, 800),
('arnold_chiari', 'Malformazione di Arnold-Chiari', '{}'::text[], 'rara', 'neuro', 'RN0010', null, '{}'::text[], 'Discesa delle tonsille cerebellari nel forame magno; spesso riscontro occasionale alla risonanza.', array['Cefalea occipitale scatenata da tosse o sforzo', 'Apnee nel sonno, difficoltà a deglutire', 'Scoliosi, sintomi da siringomielia (formicolii, debolezza)'], 'Risonanza encefalo e midollo.', array['Neurochirurgo pediatra', 'Risonanza periodica secondo i sintomi'], 'Neurochirurgo pediatra', null, null, '[]'::jsonb, 810),
('sotos', 'Sindrome di Sotos', '{}'::text[], 'rara', 'genetica', 'RC0310', 821, '{}'::text[], 'Sindrome da iperaccrescimento, più spesso da varianti del gene NSD1.', array['Macrocefalia e statura elevata', 'Volto caratteristico (fronte ampia, mento appuntito)', 'Ritardo dello sviluppo', 'Età ossea avanzata'], 'Analisi del gene NSD1.', array['Sviluppo e apprendimento', 'Cardiologia e reni alla diagnosi', 'Scoliosi'], 'Genetista, neuropsichiatra infantile', null, null, '[]'::jsonb, 820),
('rubinstein_taybi', 'Sindrome di Rubinstein-Taybi', '{}'::text[], 'rara', 'genetica', 'RN1620', 783, '{}'::text[], 'Sindrome malformativa da varianti dei geni CREBBP o EP300.', array['Pollici e alluci larghi e deviati', 'Tratti del volto caratteristici', 'Ritardo dello sviluppo, bassa statura'], 'Diagnosi clinica e analisi genetica.', array['Cardiologia e reni', 'Vista (glaucoma), udito', 'Alimentazione e sviluppo'], 'Genetista', null, null, '[]'::jsonb, 830),
('charge', 'Sindrome CHARGE', '{}'::text[], 'rara', 'genetica', 'RN0850', 138, '{}'::text[], 'Sindrome malformativa, più spesso da varianti del gene CHD7.', array['Coloboma oculare', 'Cardiopatia congenita', 'Atresia delle coane (difficoltà respiratoria nel neonato)', 'Orecchie malformate e sordità', 'Ritardo di crescita, anomalie genitali'], 'Diagnosi clinica e analisi del gene CHD7.', array['Udito, vista, cardiologia', 'Alimentazione e deglutizione', 'Endocrinologia (pubertà)'], 'Genetista, team multidisciplinare', null, null, '[]'::jsonb, 840),
('kabuki', 'Sindrome Kabuki', '{}'::text[], 'rara', 'genetica', 'RN0940', 2322, '{}'::text[], 'Sindrome malformativa da varianti dei geni KMT2D o KDM6A.', array['Tratti del volto caratteristici (rime palpebrali allungate)', 'Polpastrelli prominenti', 'Ipotonia, ritardo dello sviluppo', 'Infezioni ricorrenti'], 'Diagnosi clinica e analisi genetica.', array['Cardiologia e reni', 'Udito', 'Immunologia', 'Sviluppo'], 'Genetista', null, null, '[]'::jsonb, 850),
('goldenhar', 'Sindrome di Goldenhar (spettro oculo-auricolo-vertebrale)', '{}'::text[], 'rara', 'genetica', 'RN0910', null, '{}'::text[], 'Anomalie dello sviluppo del primo e secondo arco branchiale, spesso asimmetriche.', array['Asimmetria del volto', 'Orecchio malformato, appendici preauricolari', 'Cisti dermoidi epibulbari', 'Anomalie vertebrali'], 'Diagnosi clinica, imaging, valutazioni specialistiche.', array['Udito', 'Chirurgia maxillo-facciale', 'Colonna, cuore, reni'], 'Genetista, chirurgo maxillo-facciale', null, null, '[]'::jsonb, 860),
('silver_russell', 'Sindrome di Silver-Russell', '{}'::text[], 'rara', 'genetica', 'RN1080', 813, '{}'::text[], 'Ritardo di crescita pre e post natale con macrocefalia relativa; spesso alterazioni dell''imprinting (11p15, cromosoma 7).', array['Peso basso alla nascita con circonferenza cranica conservata', 'Asimmetria corporea', 'Difficoltà di alimentazione e ipoglicemie', 'Fronte prominente, volto triangolare'], 'Criteri clinici (Netchine-Harbison) e test di metilazione.', array['Nutrizione e prevenzione delle ipoglicemie', 'Crescita (eventuale GH) e pubertà', 'Asimmetria degli arti'], 'Endocrinologo pediatra, genetista', null, null, '[]'::jsonb, 870),
('alagille', 'Sindrome di Alagille', '{}'::text[], 'rara', 'gastro', 'RN1350', 52, '{}'::text[], 'Malattia autosomica dominante (gene JAG1 o NOTCH2) con scarsità dei dotti biliari e coinvolgimento multiorgano.', array['Colestasi neonatale con prurito intenso', 'Soffio cardiaco (stenosi polmonare periferica)', 'Vertebre a farfalla, embriotoxon posteriore', 'Volto caratteristico'], 'Esami di colestasi, ecocardiogramma, radiografia della colonna, visita oculistica, analisi genetica.', array['Epatologo pediatra', 'Cardiologia, reni', 'Nutrizione e vitamine liposolubili'], 'Epatologo pediatra', null, null, '[]'::jsonb, 880)
on conflict (codice) do nothing;
